def get_hashable_block(input_grid, output_grid, i, j):
    """Extract 3x2 output block for input cell (i,j)"""
    r1 = output_grid[i*3:(i+1)*3]
    # Should get 3 rows
    block_rows = [row[j*2:(j+1)*2] for row in r1]
    # Convert to tuple of tuples for hashing
    return tuple(tuple(x) for x in block_rows)

